impl Collection {
    pub fn extract_id(v: &crate::kernel::Json) -> Result<String, crate::kernel::Refusal> {
        let by_identity = (|| -> Option<String> {
            let c0 = v.dig("agg.value")?.to_id_component().ok()?;
            Some(c0)
        })();
        let by_id_key = v.get("id").and_then(|j| j.to_id_component().ok());
        let by_reference_key = v.get("collection").and_then(|j| j.to_id_component().ok());

        by_identity.or(by_id_key).or(by_reference_key).ok_or_else(|| {
            crate::kernel::Refusal::TypeMismatch("Collection: no identity found (tried agg.value, id, collection)".to_string())
        })
    }
}

