#[derive(Debug, Clone)]
pub struct DeclareArgs {
    pub agg: SettingsText,
}

pub fn dispatch_declare(
    repo: &mut impl crate::kernel::Repository<Collection>, route: Option<&crate::kernel::RoutingEnvelope>, args: DeclareArgs, mutations: &mut Vec<crate::kernel::MutationRecord>, owner_deref: Vec<(&'static str, crate::kernel::DerefNode)>, command_deref: Vec<(&'static str, crate::kernel::DerefNode)>, tenant_boundary_check: Result<(), crate::kernel::Refusal>,
) -> crate::kernel::DispatchResult<Collection> {
        args.agg.check_invariants()?;
    let with_references = crate::kernel::WithReferences { command_deref: &command_deref, args: &args, owner_deref: &owner_deref };
    let seed_projections = crate::kernel::seeded_projections(&with_references, COLLECTION_PROJECTED_FIELDS);

    crate::kernel::dispatch(
        repo,
        match route {
        Some(__route) => {
        __route.require_depth(0)?;
        crate::kernel::Hydrate::Act { id: __route.aggregate().to_string() }
    }
        None => { let __hydrate_id: String = args.agg.value.to_string(); crate::kernel::Hydrate::Create {
        id: __hydrate_id,
        build: Box::new(|| Collection {
            agg: Some(args.agg.clone()),
            label: None,
            key: None,
            nav_order: None,
            primary_field: None,
            list_query: None,
            identity_field: None,
            identity_strategy: None,
            identity_source: None,
            identity_prefix: None,
            identity_extra_json: None,
            columns: vec![],
            detail_fields: vec![],
            detail_field_columns: vec![],
            preconditions: vec![],
            field_formats: vec![],
            extra_json: None,
        }),
        state_independent: false,
    } }
    },
        "Declare",
        "ConsoleSettings::Collection",
        "Collection",
        "agg.value",
        &with_references,
        &[
            crate::kernel::GivenSpec { description: "a collection names its own aggregate", expr: Expr::Not(Box::new(Expr::Empty(Box::new(Expr::ToS(Box::new(Expr::Lookup("agg.value"))))))), corrects_event: None },
        ],
        None,
        |record| {
        let _ = record;
            Ok(())
        },
        &[

        ],
        &collection_invariants(),
        &["CollectionDeclared"],
        args.to_json(),
        mutations,
        seed_projections,
        tenant_boundary_check,
    )
}

